CREATE TABLE IF NOT EXISTS GN_DW.LAB.FEE_MONTH_CLOSE_SNAPSHOT (
    SNAP_MT       VARCHAR(6)   NOT NULL,
    SECTION       VARCHAR(10)  NOT NULL,
    KEY1          VARCHAR(500) NOT NULL,
    KEY2          VARCHAR(500) NOT NULL,
    KEY3          VARCHAR(500) NOT NULL,
    KEY4          VARCHAR(500) NOT NULL,
    PAY_CNT       NUMBER(38,0),
    PAY_AMT       NUMBER(38,4),
    NEW_PAY_AMT   NUMBER(38,4),
    ACT_CASES     NUMBER(38,4),
    RULE_VERSION  VARCHAR(50),
    SNAP_SOURCE   VARCHAR(30),           -- AUTO_CALC / HARDCODE
    SNAP_TS       TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
    CONSTRAINT PK_FEE_MONTH_CLOSE PRIMARY KEY (SNAP_MT, SECTION, KEY1, KEY2, KEY3, KEY4)
);

